/** 🧊️ Exact BRep geometry words and reciprocal topology inspected by independent SQLite. */
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
import type {SemioBrepSnapshot,BrepCurve,BrepCurve2,BrepSurface} from "../../🟦️.ts";
import {SEMIO_BREP_SQLITE_SCHEMA,semioBrepSnapshotToSqliteDatabase,semioBrepSnapshotFromSqliteDatabase} from "../../🪶️sqlite/🟦️.ts";
import {binary64,exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const p3=()=>({x:binary64(1),y:binary64(2),z:binary64(3)}),axis=()=>({x:binary64(0),y:binary64(0),z:binary64(1)}),p2=()=>({x:binary64(1),y:binary64(2)}),knots=()=>f.knotValues.map(binary64);
const curves:BrepCurve[]=[{kind:"line",origin:p3(),direction:axis()},{kind:"circle",center:p3(),axis:axis(),radius:binary64(2.5)},{kind:"ellipse",center:p3(),axis:axis(),radiusMajor:binary64(3.5),radiusMinor:binary64(1.25)},{kind:"nurbs",controlPoints:[p3(),axis()],weights:[binary64(1),binary64(0.5)],degree:1,knots:knots()}],pcurves:BrepCurve2[]=[{kind:"line",origin:p2(),direction:p2()},{kind:"circle",center:p2(),radius:binary64(2.5)},{kind:"ellipse",center:p2(),xAxis:p2(),radiusMajor:binary64(3.5),radiusMinor:binary64(1.25)},{kind:"nurbs",controlPoints:[p2(),p2()],weights:[binary64(1),binary64(0.5)],degree:1,knots:knots()}],surfaces:BrepSurface[]=[{kind:"plane",origin:p3(),normal:axis()},{kind:"cylinder",origin:p3(),axis:axis(),radius:binary64(2.5)},{kind:"cone",origin:p3(),axis:axis(),radius:binary64(2.5),halfAngle:binary64(0.25)},{kind:"sphere",center:p3(),radius:binary64(2.5)},{kind:"torus",center:p3(),axis:axis(),majorRadius:binary64(3.5),minorRadius:binary64(1.25)},{kind:"nurbs",controlPoints:[p3(),axis()],weights:[binary64(1),binary64(0.5)],uCount:1,vCount:2,degreeU:0,degreeV:1,knotsU:[binary64(0),binary64(1)],knotsV:knots()}];
const input:SemioBrepSnapshot={schema:f.schema,nextLabel:BigInt(f.nextLabel),vertices:[{id:f.vertexIds[0]!,point:p3(),tol:binary64(0.001)},{id:f.vertexIds[1]!,point:axis(),tol:binary64(0.002)}],edges:curves.map((curve,i)=>({id:"e"+i,startVertex:f.vertexIds[0]!,endVertex:f.vertexIds[1]!,curve,tol:binary64(0.003)})),loops:[{id:"loop",edges:curves.map((_,i)=>({edge:"e"+i,orientation:i%2===0}))},{id:"inner",edges:[]}],faces:surfaces.map((surface,i)=>({id:"f"+i,outerLoop:"loop",innerLoops:["inner"],surface,orientation:i%2===0,tol:binary64(0.004)})),shells:[{id:"shell",faces:surfaces.map((_,i)=>({face:"f"+i,orientation:i%2===0}))}],solids:[{id:"solid",shells:[{shell:"shell",isVoid:false},{shell:"shell",isVoid:true}]}],coedges:pcurves.map((pcurve,i)=>({id:"c"+i,edge:"e"+i,forward:i%2===0,pcurve,prange:[binary64(-1),binary64(2)],loopId:"loop",next:"c"+((i+1)%4),prev:"c"+((i+3)%4)}))};
