fn sqlite_snapshot_semio_brep_controlled_native_output(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let mut snapshot=fixture();snapshot.schema="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioBrepSnapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioBrepSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))};assert!(actual==expected,"controlled native wire differs");
 for measure in[true,false]{let mut reached=false;let error=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=65536&&(if measure{event.total==0}else{event.total>65536&&event.completed<event.total});reached|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(reached&&error.message.contains("cancel"),"{error}");}
